import{_ as n,o as r,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const s="/assets/zaehlerstand-angleichen.DyEoA86p.png",t="/assets/einstellungen-startwerte.BMlVJq4b.png",d="/assets/zaehler-getauscht.DMhvSr40.png",f=JSON.parse('{"title":"Zählerstände korrigieren und Zähler tauschen","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/02.zaehlerstaende-korrigieren.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","filePath":"de/adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","lastUpdated":null}'),l={name:"de/adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md"};function u(o,e,h,c,g,m){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="zahlerstande-korrigieren-und-zahler-tauschen" tabindex="-1">Zählerstände korrigieren und Zähler tauschen <a class="header-anchor" href="#zahlerstande-korrigieren-und-zahler-tauschen" aria-label="Permalink to &quot;Zählerstände korrigieren und Zähler tauschen&quot;">​</a></h1><p><a id="correct-wrong-too-high-negative"></a></p><h2 id="wie-korrigiere-ich-falsche-zu-hohe-oder-negative-werte-nach-einem-reset" tabindex="-1">Wie korrigiere ich falsche, zu hohe oder negative Werte nach einem Reset? <a class="header-anchor" href="#wie-korrigiere-ich-falsche-zu-hohe-oder-negative-werte-nach-einem-reset" aria-label="Permalink to &quot;Wie korrigiere ich falsche, zu hohe oder negative Werte nach einem Reset?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 öffnest du in den Instanz-Einstellungen von SourceAnalytix die Quelle, wählst die Aktion „Zählerstand angleichen&quot; und gibst den Stand ein, den dein Zähler gerade zeigt. Den Rest erledigt SourceAnalytix sofort, ohne Neustart. Bis v0.6.x geht es nur von Hand (siehe unten), und dort reicht es nicht, nur <code>cumulativeReading</code> zu ändern.</p><p>Der Grund: Der Gesamtstand (<code>cumulativeReading</code>) ist immer Gerätewert + Offset (<code>valueAtDeviceReset</code>). Änderst du nur den Gesamtstand, überschreibt ihn der nächste Wert wieder oder hält ihn für einen Reset. Die Aktion setzt beide Werte passend zueinander. Die Begriffe sind unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a> erklärt.</p><h3 id="so-gehst-du-vor-ab-v0-7-0" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen&quot; die Einstellungen der SourceAnalytix-Instanz und dort im Tab „Übersicht&quot; deine Quelle.</li><li>Wähle bei „Aktionen&quot; den Eintrag „Zählerstand angleichen&quot;.</li><li>Trage bei „Was zeigt dein Zähler jetzt?&quot; den Stand ein, den du am Zähler abliest.</li><li>Prüfe die Vorschau. Sie zeigt den alten und den neuen Gesamtstand. Der Verbrauch von heute und die vergangenen Perioden bleiben unverändert.</li><li>Klicke auf „⚡ Angleichen&quot;. Die Werte gelten sofort.</li></ol><p><img src="'+s+'" alt="Dialog „Zählerstand angleichen“ mit Vorschau"></p><p>Meldet SourceAnalytix selbst, dass Gesamtstand und Zähler nicht zusammenpassen, steht das im Tab „Probleme&quot; mit dem Vorschlag „Zählerstand angleichen&quot;.</p><p>Die Aktion verschiebt alle Startwerte um denselben Betrag wie den Gesamtstand. Ein falscher Sprung, der schon im Verbrauch von heute, dieser Woche oder diesem Monat steckt, bleibt deshalb dort stehen. Diesen Teil entfernst du zusätzlich über die Startwerte, wie unter <a href="#values-negative-after-entering-start">So korrigierst du die Startwerte</a> beschrieben.</p><h3 id="kosten-reparieren" tabindex="-1">Kosten reparieren <a class="header-anchor" href="#kosten-reparieren" aria-label="Permalink to &quot;Kosten reparieren&quot;">​</a></h3><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Kosten werden fortlaufend aus der Änderung des Gesamtstands gebucht. Ein falscher Sprung nach oben ist deshalb schon als Kosten zum damaligen Preis gebucht, und eine Senkung des Gesamtstands verringert die Kosten nicht. Repariere die Kosten nach jeder Korrektur.</p></div><p><strong>Ab v0.7.0:</strong> Wähle bei der Quelle die Aktion „Kosten ab Datum neu rechnen&quot; und als Datum den Tag, an dem der Fehler begann. SourceAnalytix rechnet die Kosten aller betroffenen Perioden mit dem Preisverlauf neu, der Verbrauch bleibt gleich. Die Vorschau zeigt vorher, wie viele Perioden betroffen sind. Weil SourceAnalytix nur den Verbrauch je Periode kennt, verteilt es ihn gleichmäßig über die Periode: Ändert sich der Preis mitten in einer Periode, wird der Verbrauch anteilig nach Zeit auf die beiden Preise aufgeteilt. Werte in einer Historie wie InfluxDB ändert die Aktion nicht (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/947" target="_blank" rel="noreferrer">#947</a>).</p><p><strong>Bis v0.6.x:</strong> Die Kosten der laufenden Perioden lassen sich neu aufsetzen. Stoppe die Instanz, leere den State <code>sourceanalytix.0.&lt;Gerät&gt;.dynamicCostMemory</code> und setze die States <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear.costs.01_currentDay</code> bis <code>05_currentYear</code> auf 0 (bei Einspeisung <code>currentYear.earnings.…</code>). Nach dem Start rechnet SourceAnalytix sie aus Gesamtstand und Startwerten mit dem aktuellen Preis neu. Ein Preiswechsel innerhalb der laufenden Periode geht dabei verloren.</p><h3 id="vor-mitternacht-korrigieren" tabindex="-1">Vor Mitternacht korrigieren <a class="header-anchor" href="#vor-mitternacht-korrigieren" aria-label="Permalink to &quot;Vor Mitternacht korrigieren&quot;">​</a></h3><p>Um Mitternacht schreibt SourceAnalytix die Werte der abgelaufenen Perioden nach <code>previousDay</code>, <code>previousWeek</code> usw. und setzt die Startwerte auf den Gesamtstand. Diese abgeschlossenen Werte und das Archiv unter <code>&lt;Jahr&gt;</code> werden beim Angleichen nicht neu berechnet. Korrigierst du vor Mitternacht, bleibt der Fehler auf den laufenden Tag beschränkt. Schon geschriebene Werte von gestern oder aus dem Archiv änderst du von Hand, ebenso Werte in einer Historie wie InfluxDB.</p><h3 id="bis-v0-6-x-von-hand-korrigieren" tabindex="-1">Bis v0.6.x: von Hand korrigieren <a class="header-anchor" href="#bis-v0-6-x-von-hand-korrigieren" aria-label="Permalink to &quot;Bis v0.6.x: von Hand korrigieren&quot;">​</a></h3><ol><li>Notiere den echten Zählerstand und den aktuellen Wert deines Quell-Datenpunkts, beide in der Zieleinheit (Wh durch 1.000 teilen, wenn in kWh gerechnet wird). Offset = echter Zählerstand − Gerätewert. Zeigt dein Gerät schon den echten Zählerstand (z. B. Lesekopf am Stromzähler), ist der Offset 0.</li><li>Stoppe die Instanz.</li><li>Setze in den SourceAnalytix-Einstellungen des Quell-Datenpunkts die Startwerte „Tag&quot; bis „Jahr&quot; auf den Gesamtstand zu Beginn der Periode, höchstens auf den echten Zählerstand. Speichern.</li><li>Setze im Objekt des Quell-Datenpunkts unter <code>common.custom.sourceanalytix.0</code> den Wert <code>valueAtDeviceReset</code> auf den Offset (Objekte, Expertenmodus, Objekt bearbeiten).</li><li>Setze <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code> auf den echten Zählerstand.</li><li>Starte die Instanz und repariere die Kosten wie oben.</li></ol><p><strong>Ab v0.6.2:</strong> Liegt der Offset über dem Gesamtstand, etwa weil nur <code>cumulativeReading</code> gesenkt wurde, läuft die Quelle weiter, und SourceAnalytix richtet den Offset beim nächsten Wert selbst aus. Bis v0.6.1 stoppte die Quelle mit dem Fehler „Known valueAtDeviceReset &gt; known cumulative value&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a>).</p><p><strong>Siehe auch:</strong> <a href="#values-negative-after-entering-start">Negative Werte nach Startwerten</a> · <a href="#replaced-meter-device-avoid-negative">Zähler oder Gerät getauscht</a> · <a href="./../fehlerbehebung/log-meldungen#error-known-valueatdevicereset-known-cumulative">Fehler „Known valueAtDeviceReset &gt; known cumulative value&quot;</a> · <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Vorperioden (previous-States)</a></p><p><a id="values-negative-after-entering-start"></a></p><h2 id="warum-sind-meine-werte-nach-der-eingabe-von-startwerten-negativ" tabindex="-1">Warum sind meine Werte nach der Eingabe von Startwerten negativ? <a class="header-anchor" href="#warum-sind-meine-werte-nach-der-eingabe-von-startwerten-negativ" aria-label="Permalink to &quot;Warum sind meine Werte nach der Eingabe von Startwerten negativ?&quot;">​</a></h2><p><strong>Kurz:</strong> Mindestens ein Startwert ist größer als der aktuelle Gesamtstand. Der Verbrauch einer Periode ist Gesamtstand − Startwert, er wird also negativ, sobald der Startwert darüber liegt. Trage als Startwert den Gesamtstand zu Beginn der Periode in der Zieleinheit ein, nie mehr als den aktuellen <code>cumulativeReading</code>.</p><h3 id="die-haufigsten-ursachen" tabindex="-1">Die häufigsten Ursachen <a class="header-anchor" href="#die-haufigsten-ursachen" aria-label="Permalink to &quot;Die häufigsten Ursachen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was eingetragen wurde</th><th>Was passiert</th><th>Richtig</th></tr></thead><tbody><tr><td>Der Verbrauch der Periode (z. B. 350 kWh im Jahr) statt des Zählerstands</td><td>Ein kleiner Startwert lässt fast den ganzen Zählerstand als Verbrauch erscheinen</td><td>Gesamtstand zu Beginn der Periode, z. B. 12.300 kWh am 1. Januar</td></tr><tr><td>Der Zählerstand in Wh (12.300.000), obwohl die Preisdefinition in kWh rechnet</td><td>Startwert tausendmal zu groß, Verbrauch stark negativ</td><td>Wert in der Zieleinheit, also 12.300 kWh</td></tr><tr><td>Der Gerätewert, obwohl SourceAnalytix nach einem Reset mit einem Offset rechnet</td><td>Startwert passt nicht zum Gesamtstand, Verbrauch zu hoch oder negativ</td><td>Wert aus <code>cumulativeReading</code> als Maßstab nehmen, nicht den Wert des Geräts</td></tr><tr><td>Ein Startwert für „Jahr&quot; oder „Monat&quot;, der über dem von „Tag&quot; liegt</td><td>Die längere Periode wird negativ</td><td>„Tag&quot; ist immer der höchste Startwert, siehe unten</td></tr><tr><td>0 in einem Feld, nachdem die Quelle schon lief</td><td>Der ganze Gesamtstand erscheint als Verbrauch</td><td>Leere oder 0-Felder füllt SourceAnalytix nur bei der ersten Aktivierung selbst</td></tr></tbody></table><h3 id="so-korrigierst-du-die-startwerte" tabindex="-1">So korrigierst du die Startwerte <a class="header-anchor" href="#so-korrigierst-du-die-startwerte" aria-label="Permalink to &quot;So korrigierst du die Startwerte&quot;">​</a></h3><ol><li>Lies den aktuellen Gesamtstand ab: ab v0.7.0 in der Detailansicht der Quelle unter „Gesamtstand&quot;, sonst im State <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>.</li><li>Scrolle in der Detailansicht im Bereich „Einstellungen&quot; zum Abschnitt „Startwerte&quot;. Bis v0.6.x stehen die Felder im Objekt-Dialog des Datenpunkts (Reiter „Objekte&quot;, Schraubenschlüssel) unter „Startwerte für den jeweiligen Zeitraum&quot;.</li><li>Trage bei „Tag&quot;, „Woche&quot;, „Monat&quot;, „Quartal&quot; und „Jahr&quot; den Gesamtstand zu Beginn der jeweiligen Periode ein, in der Zieleinheit. <ul><li>Kennst du den Stand zu Beginn einer Periode nicht, trage den aktuellen Gesamtstand ein. Die Periode beginnt dann jetzt bei 0.</li><li>Jeder Startwert ist höchstens so groß wie der aktuelle Gesamtstand.</li><li>„Tag&quot; ist mindestens so groß wie alle anderen, denn der Tag hat zuletzt begonnen. „Monat&quot; ist mindestens so groß wie „Quartal&quot;, „Quartal&quot; mindestens so groß wie „Jahr&quot;.</li><li>„Woche&quot; ordnest du nach ihrem ersten Tag ein: Begann die Woche im Vormonat oder im Vorjahr, darf ihr Startwert unter dem von „Monat&quot; oder „Jahr&quot; liegen.</li><li>Schreib Zahlen ohne Tausenderpunkt, mit Komma oder Punkt als Dezimalzeichen: <code>12475,5</code> oder <code>12475.5</code>.</li></ul></li><li>Klicke auf „⚡ Übernehmen&quot;. Die Instanz musst du dafür nicht stoppen.</li><li>Mit dem nächsten Wert der Quelle rechnet SourceAnalytix die laufenden Perioden neu. Die Werte unter <code>currentYear</code> sind jetzt nicht mehr negativ.</li></ol><p><img src="'+t+'" alt="Bereich „Einstellungen“ der Quelle mit „Startwerte“ und aufgeklapptem „Für Experten“"></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Startwerte gelten nur für die laufende Periode. Beim nächsten Wechsel (z. B. um Mitternacht für „Tag&quot;) überschreibt SourceAnalytix sie mit dem dann aktuellen Gesamtstand. Abgeschlossene Perioden wie gestern oder der Vormonat werden durch neue Startwerte nicht neu berechnet.</p></div><p>Stimmt nicht der Startwert, sondern der Gesamtstand selbst nicht, hilft das Ändern der Startwerte nicht. Dann gehst du vor wie unter <a href="#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><p><strong>Ab v0.7.0:</strong> Die Detailansicht prüft die Startwerte wie der Assistent: Jeder geänderte Startwert muss zum aktuellen Gesamtstand und zur Reihenfolge der Perioden passen, sonst zeigt das Feld einen Fehler, und „⚡ Übernehmen&quot; bleibt gesperrt. Passt ein Wert erst geteilt durch 1000, steht dort zum Beispiel „Sieht nach Wh aus – gemeint 1,29 kWh?&quot;. Unpassende Startwerte meldet außerdem der Tab „Probleme&quot; als „Startwert passt nicht&quot; mit dem Vorschlag „Startwerte prüfen: höchstens der aktuelle Stand, in der Rechen-Einheit.&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1267" target="_blank" rel="noreferrer">#1267</a>, <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Werte viel zu hoch oder negativ – stimmt die Einheit?</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Die Begriffe</a></p><p><a id="replaced-meter-device-avoid-negative"></a></p><h2 id="ich-habe-zahler-oder-gerat-getauscht-–-wie-vermeide-ich-negative-werte" tabindex="-1">Ich habe Zähler oder Gerät getauscht – wie vermeide ich negative Werte? <a class="header-anchor" href="#ich-habe-zahler-oder-gerat-getauscht-–-wie-vermeide-ich-negative-werte" aria-label="Permalink to &quot;Ich habe Zähler oder Gerät getauscht – wie vermeide ich negative Werte?&quot;">​</a></h2><p><strong>Kurz:</strong> Lass die Reset-Erkennung eingeschaltet. Beginnt der neue Zähler deutlich unter dem alten Gesamtstand, zum Beispiel bei 0, zählt SourceAnalytix nach zwei Werten selbst weiter. In allen anderen Fällen nutzt du ab v0.7.0 die Aktion „Zähler getauscht&quot; in den Instanz-Einstellungen, am besten bevor der neue Zähler den ersten Wert liefert.</p><h3 id="was-sourceanalytix-beim-tausch-tut" tabindex="-1">Was SourceAnalytix beim Tausch tut <a class="header-anchor" href="#was-sourceanalytix-beim-tausch-tut" aria-label="Permalink to &quot;Was SourceAnalytix beim Tausch tut&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Der neue Zähler beginnt …</th><th>SourceAnalytix …</th><th>Du …</th></tr></thead><tbody><tr><td>deutlich unter dem alten Gesamtstand (mehr als die Schwelle)</td><td>erkennt einen Reset, bestätigt ihn mit dem nächsten Wert und zählt auf den alten Gesamtstand weiter</td><td>musst nichts tun. Im Log steht „Device reset detected …&quot;.</td></tr><tr><td>knapp unter dem alten Gesamtstand (höchstens die Schwelle)</td><td>hält das für eine Messschwankung und ignoriert die Werte, bis sie den alten Stand übersteigen</td><td>nutzt „Zähler getauscht&quot;.</td></tr><tr><td>auf oder über dem alten Gesamtstand</td><td>sieht keinen Reset und zählt den Sprung als Verbrauch</td><td>nutzt „Zähler getauscht&quot;.</td></tr></tbody></table><p>Die Begriffe Gesamtstand, Offset und Schwelle sind unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a> erklärt.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-1" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-1" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen&quot; die Einstellungen der SourceAnalytix-Instanz und im Tab „Übersicht&quot; deine Quelle.</li><li>Wähle bei „Aktionen&quot; den Eintrag „Zähler getauscht&quot;.</li><li>Trage den Endstand des alten Zählers, den Startstand des neuen Zählers und das Datum des Tauschs ein.</li><li>Prüfe die Vorschau und klicke auf „⚡ Tausch übernehmen&quot;. Der Gesamtstand läuft vom alten Endstand weiter, ohne Neustart.</li></ol><p><img src="'+d+'" alt="Dialog „Zähler getauscht“ mit Endstand alt, Startstand neu und Datum"></p><p>Hat der neue Zähler schon Werte geliefert und ist der Gesamtstand gesprungen, nimm stattdessen „Zählerstand angleichen&quot; und repariere die Kosten, wie unter <a href="#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> beschrieben.</p><h3 id="bis-v0-6-x-offset-von-hand-setzen" tabindex="-1">Bis v0.6.x: Offset von Hand setzen <a class="header-anchor" href="#bis-v0-6-x-offset-von-hand-setzen" aria-label="Permalink to &quot;Bis v0.6.x: Offset von Hand setzen&quot;">​</a></h3><ol><li>Stoppe die Instanz vor dem Tausch und notiere den Gesamtstand aus <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>.</li><li>Tausche den Zähler und notiere seinen Startstand in der Zieleinheit.</li><li>Offset = alter Gesamtstand − Startstand des neuen Zählers. Steht der neue Zähler höher, ist der Offset negativ, das ist richtig so.</li><li>Setze im Objekt des Quell-Datenpunkts unter <code>common.custom.sourceanalytix.0</code> den Wert <code>valueAtDeviceReset</code> auf diesen Offset (Objekte, Expertenmodus, Objekt bearbeiten) und starte die Instanz.</li></ol><p>Beispiel: Alter Gesamtstand 5.000 kWh, neuer Zähler beginnt bei 6.000 kWh, Offset −1.000. Meldet der neue Zähler später 6.010 kWh, zeigt <code>cumulativeReading</code> 5.010 kWh.</p><p><strong>Ab v0.6.2:</strong> Ist der Offset nach einem Tausch größer als der Gesamtstand, stoppt die Quelle nicht mehr, sondern SourceAnalytix richtet den Offset beim nächsten Wert selbst aus (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a>).</p><h3 id="gerat-getauscht-alias-statt-gerat-verwenden" tabindex="-1">Gerät getauscht: Alias statt Gerät verwenden <a class="header-anchor" href="#gerat-getauscht-alias-statt-gerat-verwenden" aria-label="Permalink to &quot;Gerät getauscht: Alias statt Gerät verwenden&quot;">​</a></h3><p>Bekommt das neue Gerät einen neuen Datenpunkt (z. B. ein neuer Shelly mit neuer ID), ist das für SourceAnalytix eine neue Quelle mit eigenem Ordner und eigenen Startwerten. Das vermeidest du mit einem ioBroker-Alias:</p><ol><li>Lege für den Zähler einen Alias an (z. B. unter <code>alias.0</code>), der auf den Datenpunkt des Geräts zeigt, und gib ihm die Einheit des Zählers.</li><li>Aktiviere SourceAnalytix auf dem Alias, nicht auf dem Gerät.</li><li>Beim Gerätetausch stellst du nur das Ziel des Alias auf den neuen Datenpunkt um. SourceAnalytix behält seinen Ordner und seinen Gesamtstand.</li><li>Für den Zählerstand des neuen Geräts gilt dann die Tabelle oben.</li></ol><p>Das Feld „Name&quot; in den SourceAnalytix-Einstellungen ist nur eine Anzeigebezeichnung und kein ioBroker-Alias. Einen Datenpunkt direkt zu wechseln und dabei die Daten mitzunehmen, ist für später geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Ältere Anleitungen im Forum nennen die Schlüssel <code>cumulativeValue</code>, <code>previousDeviceReset</code> oder <code>valueAtDeviceInit</code>. SourceAnalytix liest keinen davon. Ab v0.6.2 wird auch <code>valueAtDeviceInit</code> nicht mehr geschrieben (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1263" target="_blank" rel="noreferrer">#1263</a>).</p></div><p><strong>Siehe auch:</strong> <a href="#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> · <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name, Alias und Output-ID</a> · <a href="./betrieb-und-wartung#restart-datapoint-clean-up-old">Datenpunkt abschalten oder neu anfangen</a></p><p><a id="meter-restarts-after-power-loss"></a></p><h2 id="mein-zahler-startet-nach-stromausfall-oder-taglich-bei-0-–-was-stelle-ich-ein" tabindex="-1">Mein Zähler startet nach Stromausfall oder täglich bei 0 – was stelle ich ein? <a class="header-anchor" href="#mein-zahler-startet-nach-stromausfall-oder-taglich-bei-0-–-was-stelle-ich-ein" aria-label="Permalink to &quot;Mein Zähler startet nach Stromausfall oder täglich bei 0 – was stelle ich ein?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist nichts. Lass die Reset-Erkennung eingeschaltet und stelle die Schwelle kleiner ein als der Betrag, um den dein Zähler beim Neustart fällt. Dann erkennt SourceAnalytix den Neustart als Reset und zählt auf den alten Gesamtstand weiter. Ab v0.7.0 findest du beides in der Detailansicht der Quelle unter „Einstellungen&quot;.</p><p>Das gilt für Shelly, Tasmota, Steckdosen mit Energiezähler und alle anderen Geräte, deren Zählerstand nach einem Stromausfall, einem Neustart oder um Mitternacht wieder bei 0 beginnt. Wie die Erkennung im Einzelnen arbeitet, steht unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a>.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-2" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-2" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen&quot; die Einstellungen der SourceAnalytix-Instanz und im Tab „Übersicht&quot; deine Quelle.</li><li>Setze unter „Einstellungen&quot; das Häkchen „Reset-Erkennung&quot;.</li><li>Klappe „Für Experten&quot; auf und prüfe „Schwelle Reset-Erkennung&quot;. Die Schwelle steht in der Zieleinheit, also z. B. in kWh, auch wenn dein Gerät Wh liefert. Rückgänge bis zu dieser Größe ignoriert SourceAnalytix als Messschwankung. <ul><li>Zähler, der beim Stromausfall auf 0 fällt: Der Standard 1 passt, sobald der Zählerstand über 1 kWh liegt.</li><li>Tageszähler (fällt jede Nacht auf 0): Wähle einen Wert unter deinem kleinsten Tagesverbrauch, z. B. 0,1 kWh.</li><li>Zähler mit kleinen Einheiten wie m³: Wähle die Schwelle ebenfalls klein, z. B. 0,1 m³.</li></ul></li><li>Klicke auf „⚡ Übernehmen&quot;. Die Einstellung wirkt sofort, ohne Neustart.</li><li>Beim nächsten Neustart des Geräts steht im Log zuerst „Waiting for another reading before confirming a possible device reset&quot; und mit dem nächsten Wert „Device reset detected … preserving cumulative value …&quot;. Der Gesamtstand zählt danach vom alten Stand weiter.</li></ol><p>Beim Anlegen einer Quelle fragt der Assistent „Springt der Wert manchmal auf 0, z. B. nach einem Stromausfall?&quot;. Nur bei „Ja&quot; ist die Reset-Erkennung an. Bei Datenpunkten von Shelly und Tasmota ist „Ja&quot; vorgewählt, bei allen anderen „Nein&quot;. Ist sie bei einer Quelle aus, die auf 0 springt, zeigt der Tab „Probleme&quot; „Zähler springt auf 0, Reset-Erkennung ist aus&quot; mit „⚡ Einschalten&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><p><strong>Bis v0.6.x</strong> stehen beide Einstellungen im Objekt-Dialog des Datenpunkts (Reiter „Objekte&quot;, Schraubenschlüssel) unter „Berechnungseinstellungen&quot;: „Erkennung der Zurücksetzung des Gerätewerts Aktiviert&quot; und „Schwelle&quot;. Ab v0.7.0 gibt es sie dort nicht mehr (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><p><img src="'+t+'" alt="Bereich „Einstellungen“ mit „Reset-Erkennung“ und „Schwelle Reset-Erkennung“ unter „Für Experten“"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Fällt der Zähler um weniger als die Schwelle, hält SourceAnalytix das für eine Messschwankung und ignoriert alle neuen Werte, bis sie den alten Stand wieder übersteigen. Bei einem Tageszähler mit Schwelle 1 kWh und 0,6 kWh am Vortag fehlen so die ersten 0,6 kWh des neuen Tages, an einem gleich starken Tag also der ganze Tag. Stelle die Schwelle deshalb kleiner als den kleinsten Rückgang ein.</p></div><h3 id="tageszahler-die-jede-nacht-bei-0-beginnen" tabindex="-1">Tageszähler, die jede Nacht bei 0 beginnen <a class="header-anchor" href="#tageszahler-die-jede-nacht-bei-0-beginnen" aria-label="Permalink to &quot;Tageszähler, die jede Nacht bei 0 beginnen&quot;">​</a></h3><p>Tageszähler wie „Ertrag heute&quot; oder „Verbrauch heute&quot; funktionieren. Bei jedem Zurücksetzen fehlt aber der kleine Teil, den das Gerät zwischen seinem letzten Wert vor dem Zurücksetzen und seinem ersten Wert danach gezählt hat. Bietet dein Gerät auch einen Gesamtzähler, der nie zurückgesetzt wird (z. B. „Total&quot;), nimm lieber diesen.</p><h3 id="wenn-sourceanalytix-wahrend-des-stromausfalls-nicht-lief" tabindex="-1">Wenn SourceAnalytix während des Stromausfalls nicht lief <a class="header-anchor" href="#wenn-sourceanalytix-wahrend-des-stromausfalls-nicht-lief" aria-label="Permalink to &quot;Wenn SourceAnalytix während des Stromausfalls nicht lief&quot;">​</a></h3><p>Der Gesamtstand ist im State <code>cumulativeReading</code> gespeichert. Hat das Gerät neu gestartet, während SourceAnalytix gestoppt war, erkennt SourceAnalytix den Reset beim ersten Wert nach dem Start. Das klappt, solange der neue Gerätewert plus Offset noch um mehr als die Schwelle unter dem gespeicherten Gesamtstand liegt. Hat das Gerät den alten Stand bis dahin schon wieder überholt, ist der Reset nicht mehr zu erkennen. Dann korrigierst du den Gesamtstand wie unter <a href="#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><h3 id="leistung-statt-zahlerstand" tabindex="-1">Leistung statt Zählerstand <a class="header-anchor" href="#leistung-statt-zahlerstand" aria-label="Permalink to &quot;Leistung statt Zählerstand&quot;">​</a></h3><p>Eine Leistungsquelle in W kennt keinen Reset, denn SourceAnalytix summiert die Leistung selbst zu einem Zählerstand auf. Ist dir der Tageszähler zu ungenau, kannst du stattdessen die Leistung deines Geräts als Quelle nehmen. Was dabei zu beachten ist, steht unter <a href="./quellen-und-einheiten#sourceanalytix-compute-consumption-meter-reading">Kann SourceAnalytix aus Leistung Verbrauch berechnen?</a>.</p><p><strong>Ab v0.6.2:</strong> Manche Geräte melden nach einem Neustart kurz zweimal 0 und danach wieder ihren alten Stand. Bis v0.6.1 bestätigten die zwei Nullen einen Reset, und der Gesamtstand verdoppelte sich, als der alte Stand zurückkam. Ab v0.6.2 nimmt SourceAnalytix den Reset in diesem Fall zurück (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1258" target="_blank" rel="noreferrer">#1258</a>).</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a> · <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Schwelle und Abschalten der Reset-Erkennung</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Zähler, der täglich auf 0 zurückgesetzt wird</a></p><p><a id="apply-real-meter-reading-cumulativereading"></a></p><h2 id="wie-ubernehme-ich-meinen-echten-zahlerstand-cumulativereading-raw-objekt" tabindex="-1">Wie übernehme ich meinen echten Zählerstand (cumulativeReading, RAW-Objekt)? <a class="header-anchor" href="#wie-ubernehme-ich-meinen-echten-zahlerstand-cumulativereading-raw-objekt" aria-label="Permalink to &quot;Wie übernehme ich meinen echten Zählerstand (cumulativeReading, RAW-Objekt)?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 musst du dafür kein Objekt mehr bearbeiten. Öffne in den Instanz-Einstellungen die Quelle, wähle „Zählerstand angleichen&quot; und trage den Stand ein, den dein Zähler zeigt. SourceAnalytix setzt <code>cumulativeReading</code> und den Offset <code>valueAtDeviceReset</code> passend zueinander, sofort und ohne Neustart. Zeigt dein Gerät schon den echten Zählerstand, zum Beispiel über einen Lesekopf, ist nichts zu tun.</p><p>Die Schritte stehen unter <a href="#correct-wrong-too-high-negative">Wie korrigiere ich falsche Werte?</a>. Den Offset siehst du in der Detailansicht der Quelle unter „Für Experten&quot; als <code>valueAtDeviceReset</code>.</p><h3 id="warum-es-nicht-reicht-nur-cumulativereading-zu-andern" tabindex="-1">Warum es nicht reicht, nur cumulativeReading zu ändern <a class="header-anchor" href="#warum-es-nicht-reicht-nur-cumulativereading-zu-andern" aria-label="Permalink to &quot;Warum es nicht reicht, nur cumulativeReading zu ändern&quot;">​</a></h3><p>Der Gesamtstand ist immer Gerätewert + Offset. Schreibst du nur einen neuen Wert in den State <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>, rechnet SourceAnalytix beim nächsten Wert der Quelle wieder Gerätewert + alter Offset. Dein Wert hält deshalb nicht. Die Begriffe sind unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Die Begriffe</a> erklärt.</p><h3 id="warum-das-roh-objekt-gesperrt-wirkt" tabindex="-1">Warum das Roh-Objekt gesperrt wirkt <a class="header-anchor" href="#warum-das-roh-objekt-gesperrt-wirkt" aria-label="Permalink to &quot;Warum das Roh-Objekt gesperrt wirkt&quot;">​</a></h3><ul><li><strong>Es liegt woanders, als man denkt.</strong> Die Einstellungen einer Quelle stehen im Objekt des Quell-Datenpunkts unter <code>common.custom.sourceanalytix.0</code>, nicht im Ordner <code>sourceanalytix.0</code>. Dort liegt nur der State <code>cumulativeReading</code>.</li><li><strong>Es braucht den Expertenmodus.</strong> Das Objekt bearbeitest du im Reiter „Objekte&quot; nur mit eingeschaltetem Expertenmodus, und das JSON muss gültig bleiben: kein überzähliges Komma, Zahlen ohne Anführungszeichen (<code>12345.6</code>, nicht <code>&quot;12345.6&quot;</code>).</li><li><strong>SourceAnalytix schreibt selbst hinein.</strong> Bei jedem Periodenwechsel schreibt es die Startwerte, bei jedem Reset den Offset. Eine Änderung, die du bei laufender Instanz machst, kann deshalb sofort wieder überschrieben werden.</li></ul><p>Ab v0.7.0 schreibt auch die Einstellungsseite den Offset nie mit. Ihn ändern nur SourceAnalytix selbst und die Aktionen „Zählerstand angleichen&quot; und „Zähler getauscht&quot;.</p><p><strong>Bis v0.6.x</strong> geht es nur über das Roh-Objekt: Instanz stoppen, <code>valueAtDeviceReset</code> und <code>cumulativeReading</code> setzen, Startwerte prüfen, Instanz starten. Die Schritte stehen unter <a href="#correct-wrong-too-high-negative">Bis v0.6.x: von Hand korrigieren</a>.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Was ist cumulativeReading?</a> · <a href="#replaced-meter-device-avoid-negative">Zähler oder Gerät getauscht</a></p>',81)])])}const p=n(l,[["render",u]]);export{f as __pageData,p as default};
